import { preprocessImage, cosineSimilarity, ImageInput } from '../utils/image-utils';

/**
 * Cấu hình cho FaceMatcher
 */
export interface FaceMatcherConfig {
    ort: any;                    // Khởi tạo thông qua Dependency Injection (ort-web hoặc ort-node)
    similarityThreshold?: number; // Ngưỡng nhận diện khớp khuôn mặt (mặc định: 0.75 - Cosine Similarity)
}

export interface MatchResult {
    success: boolean;
    similarity: number;   // Điểm tương đồng từ 0.0 đến 1.0
    isMatch: boolean;     // Trùng khớp khuôn mặt hay không
    message: string;
}

export class FaceMatcher {
    private detectorSession: any = null;
    private recognizerSession: any = null;
    private config: FaceMatcherConfig;

    constructor(config: FaceMatcherConfig) {
        if (!config || !config.ort) {
            throw new Error("[NDieu-Face] Cần cung cấp đối tượng 'ort' (ONNX Runtime) để khởi tạo.");
        }
        this.config = {
            similarityThreshold: 0.75,
            ...config
        };
    }

    /**
     * Khởi tạo FaceMatcher bằng cách tải mô hình Phát hiện khuôn mặt (BlazeFace) và So khớp (MobileFaceNet)
     * @param detectorModel Đường dẫn URL hoặc Buffer nhị phân (Uint8Array) của mô hình BlazeFace (.onnx)
     * @param recognizerModel Đường dẫn URL hoặc Buffer nhị phân (Uint8Array) của mô hình MobileFaceNet (.onnx)
     * @param options Tùy chọn cấu hình Session cho ONNX Runtime (Mặc định sử dụng WASM)
     */
    async initialize(
        detectorModel: string | Uint8Array, 
        recognizerModel: string | Uint8Array,
        options: any = { executionProviders: ['wasm'] }
    ) {
        console.log("[NDieu-Face] Đang khởi tạo các mô hình khuôn mặt tại biên...");
        try {
            const [detectorSession, recognizerSession] = await Promise.all([
                this.config.ort.InferenceSession.create(detectorModel, options),
                this.config.ort.InferenceSession.create(recognizerModel, options)
            ]);

            this.detectorSession = detectorSession;
            this.recognizerSession = recognizerSession;
            console.log("[NDieu-Face] Khởi tạo mô hình định vị và trích xuất khuôn mặt thành công!");
        } catch (error) {
            console.error("[NDieu-Face] Lỗi khởi tạo mô hình:", error);
            throw new Error(`[NDieu] Khởi tạo FaceMatcher thất bại: ${error}`);
        }
    }

    /**
     * Trích xuất Vector Embedding từ ảnh chứa một khuôn mặt
     * @param image Ảnh chứa gương mặt cần trích xuất đặc trưng
     */
    async extractEmbedding(image: ImageInput): Promise<Float32Array> {
        if (!this.recognizerSession) {
            throw new Error("[NDieu-Face] Mô hình nhận diện khuôn mặt chưa sẵn sàng.");
        }

        console.log("[NDieu-Face] Đang trích xuất vector đặc trưng khuôn mặt...");

        // 1. Tiền xử lý ảnh: MobileFaceNet yêu cầu kích thước đầu vào là 112x112 pixel
        const targetW = 112;
        const targetH = 112;
        
        // MobileFaceNet mong đợi ảnh được chuẩn hóa theo chuẩn ảnh gương mặt (trừ 127.5 rồi chia 127.5)
        const floatBuffer = preprocessImage(image, targetW, targetH, {
            mean: [0.5, 0.5, 0.5], // pixel / 255.0 - 0.5 = (pixel - 127.5) / 255.0
            std: [0.5, 0.5, 0.5],  // / 0.5 => * 2.0 = (pixel - 127.5) / 127.5
            channelOrder: 'RGB'
        });

        // 2. Tạo Tensor đầu vào shape [1, 3, 112, 112] sử dụng thư viện được inject
        const inputTensor = new this.config.ort.Tensor('float32', floatBuffer, [1, 3, targetH, targetW]);

        // 3. Thực thi suy luận (Inference)
        const outputs = await this.recognizerSession.run({ 'input': inputTensor });
        
        // Lấy kết quả đầu ra
        const outputNames = Object.keys(outputs);
        const embeddingTensor = outputs[outputNames[0]];
        const embeddings = embeddingTensor.data as Float32Array;

        return embeddings;
    }

    /**
     * So sánh ảnh trên giấy tờ và ảnh chân dung (Selfie)
     * @param documentImage Ảnh chân dung cắt ra từ thẻ CCCD/CMND
     * @param selfieImage Ảnh selfie thực tế của khách hàng
     */
    async match(
        documentImage: ImageInput,
        selfieImage: ImageInput
    ): Promise<MatchResult> {
        try {
            console.log("[NDieu-Face] Bắt đầu quá trình so khớp khuôn mặt offline...");

            // Bước 1: Trích xuất đặc trưng của khuôn mặt 1 (Giấy tờ)
            const embeddingDoc = await this.extractEmbedding(documentImage);

            // Bước 2: Trích xuất đặc trưng của khuôn mặt 2 (Selfie)
            const embeddingSelfie = await this.extractEmbedding(selfieImage);

            // Bước 3: Tính khoảng cách Cosine giữa 2 vector embeddings
            const similarityScore = cosineSimilarity(embeddingDoc, embeddingSelfie);
            
            // Chuyển đổi và chuẩn hóa mức độ tin cậy trùng khớp
            const threshold = this.config.similarityThreshold || 0.75;
            const isMatch = similarityScore >= threshold;

            console.log(`[NDieu-Face] Kết quả so khớp - Similarity: ${similarityScore.toFixed(4)}, Threshold: ${threshold}`);

            return {
                success: true,
                similarity: similarityScore,
                isMatch: isMatch,
                message: isMatch 
                    ? "Khuôn mặt trên giấy tờ trùng khớp với ảnh selfie của người dùng." 
                    : "Khuôn mặt không khớp. Vui lòng thử lại với góc chụp và ánh sáng tốt hơn."
            };

        } catch (error) {
            console.error("[NDieu-Face] Lỗi trong quá trình so khớp:", error);
            return {
                success: false,
                similarity: 0.0,
                isMatch: false,
                message: `Lỗi so khớp offline: ${error}`
            };
        }
    }
}
