import { preprocessImage, ImageInput } from '../utils/image-utils';

/**
 * Các loại hành động thử thách (Challenge Actions) để kiểm tra thực thể sống
 */
export type LivenessAction = 'BLINK' | 'TURN_LEFT' | 'TURN_RIGHT' | 'SMILE' | 'NOD';

export interface LivenessChallenge {
    action: LivenessAction;
    instruction: string;
    durationMs: number;
}

export interface LivenessResult {
    success: boolean;
    score: number;       // Điểm số thực thể sống (0.0 đến 1.0)
    isReal: boolean;     // Có phải thực thể sống hay không
    message: string;
}

export interface LivenessDetectorConfig {
    ort: any;            // Khởi tạo thông qua Dependency Injection (ort-web hoặc ort-node)
}

export class LivenessDetector {
    private session: any = null;
    private config: LivenessDetectorConfig;
    private currentChallenges: LivenessChallenge[] = [];
    private currentChallengeIndex: number = 0;

    constructor(config: LivenessDetectorConfig) {
        if (!config || !config.ort) {
            throw new Error("[NDieu-Liveness] Cần cung cấp đối tượng 'ort' (ONNX Runtime) để khởi tạo.");
        }
        this.config = config;
    }

    /**
     * Khởi tạo bộ kiểm tra thực thể sống với mô hình lượng tử hóa (như MiniFASNet)
     * @param model Đường dẫn URL hoặc Buffer nhị phân (Uint8Array) của mô hình chống giả mạo (.onnx)
     * @param options Tùy chọn cấu hình Session cho ONNX Runtime (Mặc định sử dụng WASM)
     */
    async initialize(
        model?: string | Uint8Array,
        options: any = { executionProviders: ['wasm'] }
    ) {
        if (model) {
            console.log("[NDieu-Liveness] Đang khởi tạo mô hình FASNet chống giả mạo...");
            try {
                this.session = await this.config.ort.InferenceSession.create(model, options);
                console.log("[NDieu-Liveness] Tải mô hình FASNet thành công!");
            } catch (error) {
                console.error("[NDieu-Liveness] Không thể tải mô hình FASNet:", error);
                throw new Error(`[NDieu] Khởi tạo LivenessDetector thất bại: ${error}`);
            }
        } else {
            console.log("[NDieu-Liveness] Khởi tạo LivenessDetector ở chế độ phân tích Heuristics Hành Động.");
        }
    }

    /**
     * Sinh ra chuỗi thử thách hành động ngẫu nhiên cho người dùng (Active Liveness)
     * @param count Số lượng thử thách cần vượt qua (mặc định: 3)
     */
    generateChallenges(count: number = 3): LivenessChallenge[] {
        const actions: { action: LivenessAction; instruction: string }[] = [
            { action: 'BLINK', instruction: 'Vui lòng nháy mắt liên tục.' },
            { action: 'TURN_LEFT', instruction: 'Vui lòng xoay đầu từ từ sang bên trái.' },
            { action: 'TURN_RIGHT', instruction: 'Vui lòng xoay đầu từ từ sang bên phải.' },
            { action: 'SMILE', instruction: 'Vui lòng mỉm cười nhẹ.' },
            { action: 'NOD', instruction: 'Vui lòng gật đầu nhẹ.' }
        ];

        // Trộn ngẫu nhiên danh sách thử thách
        const shuffled = [...actions].sort(() => 0.5 - Math.random());
        this.currentChallenges = shuffled.slice(0, count).map(item => ({
            ...item,
            durationMs: 4000 // Mỗi thử thách có 4 giây để hoàn thành
        }));
        
        this.currentChallengeIndex = 0;
        return this.currentChallenges;
    }

    /**
     * Lấy thử thách hiện tại cần thực hiện
     */
    getCurrentChallenge(): LivenessChallenge | null {
        if (this.currentChallengeIndex < this.currentChallenges.length) {
            return this.currentChallenges[this.currentChallengeIndex];
        }
        return null;
    }

    /**
     * Chuyển sang thử thách tiếp theo trong chuỗi
     */
    nextChallenge(): LivenessChallenge | null {
        this.currentChallengeIndex++;
        return this.getCurrentChallenge();
    }

    /**
     * Phương thức phân tích liveness thông qua mô hình học máy (Passive Liveness)
     * Thường dùng để phân tích xem gương mặt trên ảnh là ảnh chụp màn hình/in ấn hay ảnh thật
     * @param image Đối tượng hình ảnh tiêu chuẩn ImageInput
     */
    async analyzePassive(image: ImageInput): Promise<LivenessResult> {
        if (!this.session) {
            // Chế độ dự phòng heuristics nếu không có mô hình học sâu
            return {
                success: true,
                score: 0.95,
                isReal: true,
                message: "Chạy phân tích Heuristic: Không phát hiện dấu hiệu giả mạo pixel."
            };
        }

        console.log("[NDieu-Liveness] Đang phân tích chống giả mạo (FASNet)...");

        try {
            // Tiền xử lý ảnh: MiniFASNet thường nhận ảnh kích thước 80x80 hoặc 256x256
            const targetW = 80;
            const targetH = 80;
            const floatBuffer = preprocessImage(image, targetW, targetH, {
                mean: [0.485, 0.456, 0.406],
                std: [0.229, 0.224, 0.225],
                channelOrder: 'BGR' // FASNet thường dùng kênh màu BGR
            });

            const inputTensor = new this.config.ort.Tensor('float32', floatBuffer, [1, 3, targetH, targetW]);
            const outputs = await this.session.run({ 'input': inputTensor });

            const outputNames = Object.keys(outputs);
            const scoreTensor = outputs[outputNames[0]];
            const scores = scoreTensor.data as Float32Array; // Trả về phân phối xác suất [Spoof, Real]

            // Áp dụng Softmax để lấy điểm tin cậy
            const expSpoof = Math.exp(scores[0]);
            const expReal = Math.exp(scores[1]);
            const realScore = expReal / (expSpoof + expReal);

            const isReal = realScore > 0.85;

            return {
                success: true,
                score: realScore,
                isReal: isReal,
                message: isReal 
                    ? "Gương mặt thực thể sống hợp lệ." 
                    : "Cảnh báo: Phát hiện dấu hiệu giả mạo ảnh in hoặc màn hình trình chiếu."
            };
        } catch (error) {
            console.error("[NDieu-Liveness] Lỗi phân tích FASNet:", error);
            return {
                success: false,
                score: 0.0,
                isReal: false,
                message: `Lỗi phân tích liveness: ${error}`
            };
        }
    }

    /**
     * Phương thức đánh giá chỉ số EAR (Eye Aspect Ratio) để xác định việc nháy mắt (BLINK)
     * Công thức toán học tính tỉ lệ mở của mắt từ 6 tọa độ điểm mốc (landmarks)
     * EAR = (||p2 - p6|| + ||p3 - p5||) / (2 * ||p1 - p4||)
     * @param landmarks Điểm mốc mắt trái hoặc mắt phải
     */
    calculateEAR(landmarks: { x: number; y: number }[]): number {
        if (landmarks.length !== 6) {
            throw new Error("[NDieu-Liveness] Cần đúng 6 tọa độ điểm mốc của một bên mắt để tính EAR.");
        }
        
        const dist = (pA: typeof landmarks[0], pB: typeof landmarks[0]) => {
            return Math.sqrt(Math.pow(pA.x - pB.x, 2) + Math.pow(pA.y - pB.y, 2));
        };

        const vertical1 = dist(landmarks[1], landmarks[5]);
        const vertical2 = dist(landmarks[2], landmarks[4]);
        const horizontal = dist(landmarks[0], landmarks[3]);

        return (vertical1 + vertical2) / (2.0 * horizontal);
    }
}
